// Recompiler runtime: guest -> native calls.
#include <dlfcn.h>
#include <stdatomic.h>

#include "rc.h"
#include "rc_call.h"

// Generated by tools/ws7/recomp/thunks/gen_thunks.py (thunks.c); absent in
// builds that have no import thunks.
__attribute__((weak)) rc_fn rc_import_thunk(uint64_t host);
#include "rc_rt.h"  // rc_tramp_guest_of (rc_tramp.c), rc_unwind_sync (rc_thread.c)

// --- native functions that return a struct through x8 ----------------------------------------
// x86-64 passes the hidden result pointer in rdi (and returns it in rax); arm64 in x8. A call through
// a bare function pointer has no signature to tell, so functions are registered by address (the
// thunks do it for function pointers whose type returns a struct, and returned by native code).
#define NSRET 512
static _Atomic uint64_t sret_tab[NSRET];  // open addressing, 0 = free

void rc_native_register_sret(const void *fn) {
  uint64_t f = (uint64_t)fn;
  if (!f) return;
  for (unsigned h = (unsigned)((f >> 2) * 0x9E3779B97F4A7C15ull >> 55) & (NSRET - 1), n = 0; n < NSRET;
       h = (h + 1) & (NSRET - 1), n++) {
    uint64_t cur = atomic_load(&sret_tab[h]);
    if (cur == f) return;
    if (!cur) {
      uint64_t zero = 0;
      if (atomic_compare_exchange_strong(&sret_tab[h], &zero, f) || zero == f) return;
    }
  }
  rc_fail("too many native sret functions", f);
}

int rc_native_is_sret(uint64_t f) {
  for (unsigned h = (unsigned)((f >> 2) * 0x9E3779B97F4A7C15ull >> 55) & (NSRET - 1), n = 0; n < NSRET;
       h = (h + 1) & (NSRET - 1), n++) {
    uint64_t cur = atomic_load(&sret_tab[h]);
    if (cur == f) return 1;
    if (!cur) return 0;
  }
  return 0;
}

// The sret form of the bridge: rdi = result pointer, rsi rdx rcx r8 r9 and the stack words at
// rsp+stack_off become x0..x7; the pointer goes in x8 and comes back in rax.
static void native_sret(rc_ctx *c, uint64_t fn, unsigned stack_off) {
  uint64_t sp = c->r[4] + stack_off;
  uint64_t ix[8] = {c->r[6], c->r[2], c->r[1], c->r[8], c->r[9],
                    RC_LD(uint64_t, sp), RC_LD(uint64_t, sp + 8), RC_LD(uint64_t, sp + 16)};
  uint64_t dx[8], ret[4];
  for (int k = 0; k < 8; k++) dx[k] = c->x[k][0];
  uint64_t res = c->r[7];
  rc_native_call_x8(fn, ix, dx, ret, res);
  rc_unwind_sync(c, &ret);
  c->r[0] = res;
}

void rc_icall_native(rc_ctx *c, uint64_t host) {
  // The call pushed a return address: it is at rsp, and the first stack
  // argument at rsp+8.
  if (rc_import_thunk) {
    rc_fn t = rc_import_thunk(host);
    if (t) {  // a bound import stored as a pointer: use its typed thunk
      c->r[4] += 8;  // pop the return address; the thunk wants stack args at rsp
      t(c);
      return;
    }
  }
  uint64_t g = rc_tramp_guest_of(host);
  if (g) {  // a trampoline of a guest function (a handler the game gave away and got back): run it directly,
    rc_fn f = rc_lookup(g);  // with the guest's own convention (hidden pointer in rdi, no narrow-result fix-up)
    if (!f) rc_fail("indirect call to untranslated code", g - rc_slide);
    f(c);
    return;
  }
  if (rc_native_is_sret(host)) native_sret(c, host, 8);
  else rc_native_generic(c, host, 8);
  c->r[4] += 8;
}

// The untyped bridge: rdi rsi rdx rcx r8 r9 and the two stack words at
// rsp+stack_off become x0..x7, xmm0..7 become d0..d7; x0, x1, d0, d1 come back
// as rax, rdx, xmm0, xmm1. Exact for every callee whose arguments are
// integers, pointers, floats and doubles that fit in both ABIs' registers.
void rc_native_generic(rc_ctx *c, uint64_t fn, unsigned stack_off) {
  uint64_t sp = c->r[4] + stack_off;
  uint64_t ix[8] = {c->r[7], c->r[6], c->r[2], c->r[1], c->r[8], c->r[9],
                    RC_LD(uint64_t, sp), RC_LD(uint64_t, sp + 8)};
  uint64_t dx[8], ret[4];
  for (int k = 0; k < 8; k++) dx[k] = c->x[k][0];
  rc_native_call(fn, ix, dx, ret);
  rc_unwind_sync(c, &ret);  // the callee may have longjmp'd over its own callbacks
  c->r[0] = ret[0];
  c->r[2] = ret[1];
  c->x[0] = (rc_v128){ret[2], 0};
  c->x[1] = (rc_v128){ret[3], 0};
}

// simd_float4x4 __invert_f4(simd_float4x4) (libsystem_m, behind simd_inverse).
// x86_64 SysV passes the 64-byte matrix in memory: the argument at the guest
// rsp (an import call pushes no return address) and the result through the
// hidden pointer in rdi, returned in rax. arm64 passes and returns it in v0-v3.
void rc_simd_invert_f4(rc_ctx *c) {
  typedef float v4 __attribute__((ext_vector_type(4)));
  typedef struct { v4 col[4]; } m4;
  static m4 (*fn)(m4);
  if (!fn) {
    fn = (m4 (*)(m4))dlsym(RTLD_DEFAULT, "__invert_f4");
    if (!fn) rc_fail("__invert_f4 not found", 0);
  }
  m4 a, r;
  memcpy(&a, (const void *)(uintptr_t)c->r[4], sizeof a);
  r = fn(a);
  memcpy((void *)(uintptr_t)c->r[7], &r, sizeof r);
  c->r[0] = c->r[7];
}
